dashboard.definition:
{
	"title": "SD-WAN and Network Health Monitoring",
	"description": "Correlate WAN health, reachability, and service-impact signals across the mesh.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Hybrid Mesh Firewalling",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# SD-WAN and Network Health Monitoring\nCorrelate WAN health, reachability, and service-impact signals across the mesh."
			}
		},
		"viz_monitoring_sdwan_circuit_state_summary": {
			"type": "splunk.pie",
			"title": "Circuit State Up vs Down",
			"dataSources": {
				"primary": "ds_monitoring_sdwan_circuit_state_summary"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"seriesColors": [
					"#2563EB",
					"#8bd45b",
					"#ff9a4a",
					"#ff7169"
				]
			},
			"description": "Counts of SD-WAN WAN-transport circuits (physical/virtual interfaces carrying a TLOC color) that are currently Up vs Down. Mirrors the Circuits tile on Monitor → Overview."
		},
		"viz_monitoring_sdwan_site_health_map": {
			"type": "splunk.map",
			"title": "Site Health Map",
			"dataSources": {
				"primary": "ds_monitoring_sdwan_site_health_map"
			},
			"options": {
				"layers": [
					{
						"type": "marker",
						"latitude": "> primary | seriesByName('lat')",
						"longitude": "> primary | seriesByName('lon')",
						"markerColor": "#53bfff",
						"resultLimit": 250,
						"tooltipHeaderField": "site_name",
						"additionalTooltipFields": [
							"site_id",
							"site_name",
							"site_health",
							"healthScore"
						]
					}
				],
				"center": [
					20,
					-20
				],
				"showScale": false,
				"showZoomControls": true,
				"zoom": 0.8,
				"backgroundColor": "#0f1a2a"
			},
			"description": "Per-site geo-tagged rollup of overall Site Health for the SD-WAN map view. Uses the GPS coordinates reported by vManage so it does not require an external lookup."
		},
		"viz_monitoring_sdwan_site_health_table": {
			"type": "splunk.table",
			"title": "Site Health Table",
			"dataSources": {
				"primary": "ds_monitoring_sdwan_site_health_table"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Per-site health table from the SD-WAN Manager Monitor → Sites view: Site ID , Site Name , Site Role , overall Site Health , plus the devices , tunnels , and apps sub-scores."
		},
		"viz_monitoring_sdwan_site_state_summary": {
			"type": "splunk.pie",
			"title": "Site State Up vs Down",
			"dataSources": {
				"primary": "ds_monitoring_sdwan_site_state_summary"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"seriesColors": [
					"#2563EB",
					"#8bd45b",
					"#ff9a4a",
					"#ff7169"
				]
			},
			"description": "Counts of SD-WAN sites by overall health bucket (good / fair / poor / no_data) using the most recent poll per site. Mirrors the Overview tile that summarises Sites Up/Down on Monitor → Overview."
		},
		"viz_secure_networking_sdwan_tunnel_health_log": {
			"type": "splunk.table",
			"title": "SD-WAN Tunnel Health Status Log",
			"dataSources": {
				"primary": "ds_secure_networking_sdwan_tunnel_health_log"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Current health status of all Cisco Catalyst SD-WAN tunnels including latency, jitter, and packet loss metrics, providing the per-tunnel performance view for the Secure Infrastructure pillar."
		},
		"viz_monitoring_sdwan_tunnel_health_poor_trend": {
			"type": "splunk.line",
			"title": "Poor Tunnels by Latency Trend",
			"dataSources": {
				"primary": "ds_monitoring_sdwan_tunnel_health_poor_trend"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#2563EB",
					"#8bd45b",
					"#ff9a4a",
					"#ff7169"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"lineWidth": 2,
				"nullValueDisplay": "gaps",
				"dataValuesDisplay": "minmax"
			},
			"description": "Time series of the count of poor-latency SD-WAN tunnels per 15-minute bucket. Mirrors the Overview → Tunnel Health (Latency, Poor Tunnels) tile."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Network operations and service-assurance teams  •  **Sources:** Catalyst SD-WAN Manager site, circuit, tunnel, and health telemetry  •  **Reading guide:** Use state distribution for posture, then move into site detail and geography.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### WAN service health\nUse state distribution for posture, then move into site detail and geography."
			}
		}
	},
	"dataSources": {
		"ds_monitoring_sdwan_circuit_state_summary": {
			"name": "Monitoring - SD-WAN - Circuit State Up vs Down",
			"options": {
				"ref": "monitoring_sdwan_circuit_state_summary",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_monitoring_sdwan_site_health_map": {
			"name": "Monitoring - SD-WAN - Site Health Map",
			"options": {
				"ref": "monitoring_sdwan_site_health_map",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_monitoring_sdwan_site_health_table": {
			"name": "Monitoring - SD-WAN - Site Health Table",
			"options": {
				"ref": "monitoring_sdwan_site_health_table",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_monitoring_sdwan_site_state_summary": {
			"name": "Monitoring - SD-WAN - Site State Up vs Down",
			"options": {
				"ref": "monitoring_sdwan_site_state_summary",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_sdwan_tunnel_health_log": {
			"name": "Secure Networking - SD-WAN Tunnel Health Status Log",
			"options": {
				"ref": "secure_networking_sdwan_tunnel_health_log",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_monitoring_sdwan_tunnel_health_poor_trend": {
			"name": "Monitoring - SD-WAN - Poor Tunnels by Latency Trend",
			"options": {
				"ref": "monitoring_sdwan_tunnel_health_poor_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1626,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 118
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 19,
							"w": 80,
							"h": 80
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 132,
							"y": 8,
							"w": 1268,
							"h": 102
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 138,
							"w": 1400,
							"h": 92
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 250,
							"w": 1400,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_monitoring_sdwan_circuit_state_summary",
						"position": {
							"x": 20,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_monitoring_sdwan_site_health_map",
						"position": {
							"x": 730,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_monitoring_sdwan_site_health_table",
						"position": {
							"x": 20,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_monitoring_sdwan_site_state_summary",
						"position": {
							"x": 730,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_sdwan_tunnel_health_log",
						"position": {
							"x": 20,
							"y": 1198,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_monitoring_sdwan_tunnel_health_poor_trend",
						"position": {
							"x": 730,
							"y": 1198,
							"w": 690,
							"h": 408
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
